iterator insert_unique_hint(tree *self, iterator position,
                            const value_type &v) {
  if (position._M_node == self->_M_header->left) {
    if (self->_M_node_count > 0 &&
        stringx_less(v.first, position._M_node->value.first))
      return tree_insert(self, position._M_node, position._M_node, v);
    else
      return insert_unique_value(self, v).first;
  } else if (position._M_node == self->_M_header) {
    if (stringx_less(self->_M_header->right->value.first, v.first))
      return tree_insert(self, 0, self->_M_header->right, v);
    else
      return insert_unique_value(self, v).first;
  } else {
    iterator before = position;
    --before;
    if (stringx_less(before._M_node->value.first, v.first) &&
        stringx_less(v.first, position._M_node->value.first)) {
      if (before._M_node->right == 0)
        return tree_insert(self, 0, before._M_node, v);
      else
        return tree_insert(self, position._M_node, position._M_node, v);
    } else
      return insert_unique_value(self, v).first;
  }
}
